CREATE PROCEDURE transfer(IN from_id INT, IN to_id INT, IN amt DECIMAL(10,2))
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;       -- any error -> undo everything
    RESIGNAL;
  END;

  START TRANSACTION;
    UPDATE Accounts SET balance = balance - amt
     WHERE id = from_id AND balance >= amt;  -- guard: no overdraft
    IF ROW_COUNT() = 0 THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Insufficient funds or account not found';
    END IF;
    UPDATE Accounts SET balance = balance + amt WHERE id = to_id;
  COMMIT;
END;

-- DEADLOCK: opposite lock order
-- T1:                          T2:
-- BEGIN;                       BEGIN;
-- UPDATE Accounts SET ... WHERE id = 1;   UPDATE Accounts SET ... WHERE id = 2;
-- UPDATE Accounts SET ... WHERE id = 2;   UPDATE Accounts SET ... WHERE id = 1;
--          ^ T1 waits on 2          ^ T2 waits on 1  -> cycle -> deadlock

-- FIX: every transaction acquires the row locks in the SAME order
-- (ascending id) BEFORE doing the real updates. Lock both rows first,
-- then apply debit/credit to the CORRECT accounts (from_id/to_id).
BEGIN;
  -- Lock the two rows in a deterministic order so no cycle can form.
  SELECT id FROM Accounts
   WHERE id IN (from_id, to_id)
   ORDER BY id
   FOR UPDATE;

  UPDATE Accounts SET balance = balance - 100 WHERE id = from_id;
  UPDATE Accounts SET balance = balance + 100 WHERE id = to_id;
COMMIT;
-- With a consistent lock order, no circular wait can form.

-- T2 (runs and commits between T1's two reads):
-- BEGIN; UPDATE Accounts SET balance = 500 WHERE id = 1; COMMIT;

-- T1:
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ; -- vs READ COMMITTED
BEGIN;
  SELECT balance FROM Accounts WHERE id = 1;  -- reads, say, 100
  -- ... T2 commits balance = 500 here ...
  SELECT balance FROM Accounts WHERE id = 1;
  -- READ COMMITTED  -> 500 (non-repeatable read)
  -- REPEATABLE READ -> 100 (stable snapshot)
COMMIT;
